// Drift detector: output-shape conformance per role (plain JS)
function detectDrift(role, output) {
  const shapes = {
    reviewer: ["verdict", "fixes"],       // ONLY these keys allowed
    triage: ["category", "confidence"],
    drafter: ["reply"],
  };
  const allowed = shapes[role] || [];
  const extra = Object.keys(output).filter((k) => !allowed.includes(k));
  return extra.length ? { drift: true, extra } : { drift: false };
}
// Reviewer returning {verdict, fixes, rewrittenCopy} → drift: [rewrittenCopy].
// Shapes enforce mandates; detectors run in eval, not production hot paths.

